def resumen(ventas):
    """Agrupa por (provincia, categoria) contando pedidos y sumando totales."""
    grupos = {}
    for v in ventas:
        g = grupos.setdefault((v["provincia"], v["categoria"]), {"pedidos": 0, "total": 0})
        g["pedidos"] += 1
        g["total"] += v["total"]
    return grupos


