def subtotal(cantidad_txt, precio_txt, descuento_txt):
    """Convierte una línea de venta y devuelve su subtotal; rechaza datos inválidos."""
    cantidad = int(cantidad_txt)
    precio = int(precio_txt)
    descuento = float(descuento_txt)
    if cantidad <= 0:
        raise ValueError(f"cantidad inválida: {cantidad}")
    if not 0 <= descuento < 1:
        raise ValueError(f"descuento fuera de rango: {descuento}")
    return cantidad * precio * (1 - descuento)


