import csv


def validar_fila(fila):
    """Convierte una fila del CSV y lanza ValueError si algún dato es inválido."""
    if not fila["categoria"].strip():
        raise ValueError("categoría vacía")
    try:
        cantidad = int(fila["cantidad"])
        precio = int(fila["precio_unitario"])
        descuento = float(fila["descuento"])
    except ValueError:
        raise ValueError("hay un número que no se puede convertir")
    if cantidad <= 0 or precio <= 0:
        raise ValueError("cantidad y precio deben ser mayores que 0")
    if not 0 <= descuento < 1:
        raise ValueError(f"descuento {descuento} fuera de rango")
    return {"fecha": fila["fecha"], "categoria": fila["categoria"],
            "cantidad": cantidad, "precio_unitario": precio, "descuento": descuento}


def cargar_ventas(ruta):
    """Devuelve (validas, errores) a partir de un CSV de ventas."""
    validas, errores = [], []
    try:
        with open(ruta, newline="", encoding="utf-8") as f:
            for numero, fila in enumerate(csv.DictReader(f), start=2):
                try:
                    validas.append(validar_fila(fila))
                except ValueError as e:
                    errores.append((numero, str(e)))
    except FileNotFoundError:
        raise FileNotFoundError(f"no existe el archivo de ventas {ruta}")
    return validas, errores


with open("ventas_reto.csv", "w", newline="", encoding="utf-8") as f:
    f.write("fecha,categoria,cantidad,precio_unitario,descuento\n")
    f.write("2026-09-03,Artesanía,2,2500,0.0\n")
    f.write("2026-09-04,Ropa,tres,9500,0.0\n")
    f.write("2026-09-06,Tecnología,4,29900,0.0\n")
    f.write("2026-09-10,,1,11500,0.0\n")
    f.write("2026-09-12,Café y bebidas,1,3800,1.2\n")
    f.write("2026-09-15,Snacks y dulces,1,2450,0.05\n")

validas, errores = cargar_ventas("ventas_reto.csv")
print("Filas válidas:", len(validas))
for numero, mensaje in errores:
    print(f"Línea {numero}: {mensaje}")
